}) }}

={{ JSON.stringify({
  filterGroups: [{ filters: [
    { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' },
    { propertyName: 'notes_last_updated', operator: 'LT', value: String(Date.now() - 7 * 864e5) }
  ]}],
  properties: ['dealname', 'dealstage', 'notes_last_updated', 'hubspot_owner_id'],
  limit: 10
}) }}

parameters.jsCode:
const call = $('Call first').first().json.results || [];
const cold = $('Going cold').first().json.results || [];
const days = d => d ? Math.floor((Date.now() - new Date(d)) / 864e5) + ' days' : 'never';
const lines = ['☕ CRM · today'];
lines.push(call.length ? '📞 Call first:\n' + call.map((c, i) => `${i + 1}. ${c.properties.company || ''} ${c.properties.firstname || ''} ${c.properties.phone || ''} · score ${c.properties.harvest_score} · ${c.properties.lead_source || ''}`.replace(/\s+/g, ' ')).join('\n') : '📞 No new leads to call first.');
lines.push(cold.length ? '🥶 Going cold:\n' + cold.map(d => `• ${d.properties.dealname} · quiet ${days(d.properties.notes_last_updated)}`).join('\n') : '🥶 No deals going cold.');
return [{ json: { text: lines.join('\n\n') } }];
